        .setting-item input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 18px; height: 18px; background: var(--theme-accent-orange); border-radius: 50%; cursor: pointer; border: 2px solid var(--theme-bg-dark); box-shadow: var(--shadow-subtle); transition: background-color 0.2s ease; }
        .setting-item input[type="range"]::-webkit-slider-thumb:hover { background: var(--theme-accent-orange-light); }
        .setting-item input[type="range"]::-moz-range-thumb { width: 16px; height: 16px; background: var(--theme-accent-orange); border-radius: 50%; cursor: pointer; border: 2px solid var(--theme-bg-dark); box-shadow: var(--shadow-subtle); transition: background-color 0.2s ease; }
        .setting-item input[type="range"]::-moz-range-thumb:hover { background: var(--theme-accent-orange-light); }
        .setting-item #font-size-value { flex-basis: 40px; flex-shrink: 0; text-align: right; font-size: 13px; color: var(--theme-text-light); }
        .setting-item input[type="color"] { -webkit-appearance: none; appearance: none; width: 40px; height: 30px; border: 1px solid var(--theme-border-light); border-radius: var(--border-radius-small); padding: 0; cursor: pointer; background-color: transparent; box-shadow: var(--shadow-subtle); transition: border-color 0.2s ease, box-shadow 0.2s ease; }
        .setting-item input[type="color"]::-webkit-color-swatch-wrapper { padding: 0; }
        .setting-item input[type="color"]::-webkit-color-swatch { border: none; border-radius: calc(var(--border-radius-small) - 1px); }
        .setting-item input[type="color"]:hover { border-color: var(--theme-accent-orange-light); box-shadow: var(--shadow-medium); }
        .setting-item input[type="checkbox"] { width: 18px; height: 18px; cursor: pointer; accent-color: var(--theme-accent-orange); margin-left: 5px; flex-grow: 0; }
        .settings-actions { display: flex; justify-content: flex-end; gap: 15px; padding-top: 20px; border-top: 1px solid var(--theme-border-light); flex-shrink: 0; }
        .settings-action-button { padding: 10px 20px; border-radius: var(--border-radius-small); cursor: pointer; transition: all 0.2s ease; border: none; font-family: var(--font-main); font-size: 14px; font-weight: 500; display: inline-flex; align-items: center; justify-content: center; box-shadow: var(--shadow-subtle); text-shadow: 1px 1px 1px rgba(0,0,0,0.2); }
