        .saved-item-container {
            display: flex;
            align-items: center;
            gap: 8px; /* Space between main button and delete button */
            margin-bottom: 8px; /* Keep original spacing */
        }
        .saved-item-container .saved-item-button {
            flex-grow: 1; /* Main button takes available space */
            margin-bottom: 0; /* Remove margin from main button itself */
        }
        .delete-item-button {
            flex-shrink: 0; /* Prevent delete button from shrinking */
            background-color: #c62828; /* Red background */
            color: white;
            border: none;
            border-radius: var(--border-radius-small);
            padding: 6px 9px; /* Smaller padding */
            font-size: 13px; /* Slightly smaller font */
            line-height: 1;
            cursor: pointer;
            transition: all 0.2s ease;
            box-shadow: var(--shadow-subtle);
        }
        .delete-item-button:hover {
            background-color: #e53935; /* Darker red on hover */
            box-shadow: var(--shadow-medium);
            transform: scale(1.05);
        }
        .delete-item-button i {
            display: block; /* Ensure icon is centered */
        }
        /* --- End Styles for Individual Delete Buttons --- */

